import os,re,glob,time
base=os.path.expanduser("~/.local/share/copyq/copyq")
pats = {
 'PGP-private': rb'BEGIN PGP PRIVATE KEY',
 'PGP-msg': rb'BEGIN PGP MESSAGE',
 'JWT': rb'eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{6,}',
 'AWS-AKIA': rb'AKIA[0-9A-Z]{16}',
 'GitHub': rb'(ghp_|github_pat_)[A-Za-z0-9]{20,}',
 'OpenAI/sk': rb'sk-[A-Za-z0-9]{20,}',
 'Slack': rb'xox[baprs]-[A-Za-z0-9-]{10,}',
 'generic-assign': rb'(?i)(password|passwd|secret|token|api[_-]?key)\s*[:=]\s*\S{6,}',
 'keychain-like': rb'keyring|keepass|bitwarden|1password',
}
hits={k:0 for k in pats}; where={k:set() for k in pats}
for p in glob.glob(base+"/**/*", recursive=True):
    if not os.path.isfile(p): continue
    try: b=open(p,'rb').read()
    except: continue
    for k,rx in pats.items():
        if re.search(rx,b):
            hits[k]+=1; where[k].add(os.path.basename(p)[:12])
for k in pats:
    if hits[k]: print(f"  {k}: {hits[k]} файл(ов) -> {sorted(where[k])}")
print("  (пусто по всем = высокоточных секретов не найдено)")
